const settings = $('Report Setting').first().json;
const orders = $input.all().map(item => item.json);
const num = value => Number(String(value ?? '').replace(/[^0-9.-]/g, '')) || 0;

const revenue = orders.reduce((sum, o) => sum + num(o.Total), 0);
const units = orders.reduce((sum, o) => sum + num(o.Quantity), 0);

const groupBy = column => Object.entries(
  orders.reduce((totals, o) => {
    totals[o[column]] = (totals[o[column]] || 0) + num(o.Total);
    return totals;
  }, {})
)
  .sort((a, b) => b[1] - a[1])
  .map(([name, total]) => ({ name, total: Math.round(total), share: Math.round((total / revenue) * 100) }));

const dates = orders.map(o => new Date(o['Order Date'])).sort((a, b) => a - b);
const fmt = d => d.toISOString().slice(0, 10);

return [{
  json: {
    days: settings.days,
    from: fmt(dates[0]),
    to: fmt(dates[dates.length - 1]),
    orders: orders.length,
    revenue: Math.round(revenue),
    units,
    averageOrder: Math.round(revenue / orders.length),
    topProducts: groupBy('Product').slice(0, 5),
    byRegion: groupBy('Region'),
    byChannel: groupBy('Channel'),
    byCategory: groupBy('Category'),
  },
}];

